fn compile_and_expect_max_slots_error(yaml: &str) -> Result<(), String> {
    let source = crate::parse_workflow_source(yaml)
        .map_err(|e| format!("parse error: {e:?}"))?;
    let result = compile_source(&source);
    match result {
        Err(errors) => {
            if errors.0.is_empty() {
                return Err("expected compile errors, got none".into());
            }
            let first = &errors.0[0];
            match first {
                crate::CompileError::Workflow(vb_core::workflow::WorkflowError::ResourceContractExceeded { resource }) => {
                    if *resource == "max_slots" {
